parameters.jsCode:
const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  const result = JSON.parse(cleaned);

  return [
    {
      json: {
        ...result,
        parse_status: "success"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        parse_status: "failed",
        parse_error: error.message,
        raw_output: raw
      }
    }
  ];
}

const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  const report = JSON.parse(cleaned);

  return [
    {
      json: {
        report_type:
          report.report_type || "AI Ticket Routing Report",

        ticket:
          report.ticket || {},

        classification:
          report.classification || {},

        priority:
          report.priority || {},

        routing:
          report.routing || {},

        customer_impact:
          report.customer_impact || "Unknown",

        business_impact:
          report.business_impact || "Unknown",

        required_action:
          report.required_action || "Unknown",

        escalation_required:
          report.escalation_required ?? false,

        human_agent_required:
          report.human_agent_required ?? false,

        evidence:
          report.evidence || [],

        routing_summary:
          report.routing_summary || "Unknown",

        recommended_next_action:
          report.recommended_next_action || "Unknown",

        parse_status: "success"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        report_type: "AI Ticket Routing Report",
        parse_status: "failed",
        parse_error: error.message,
        raw_output: raw
      }
    }
  ];
}
